import * as React from 'react'
import { cn } from '@/lib/utils'
import { useSlidingIndicator } from '@/hooks/use-sliding-indicator'
import { isRTL } from '@/lib/direction'
import { useTabBarFade } from '@/hooks/use-tab-bar-fade'
import { useReducedMotion } from '@/hooks/use-reduced-motion'
import { ProgressBar } from '@/components/ui/progress-bar'

export interface TabBarItem {
  id: string
  label: string
  /**
   * Optional leading icon, shown before the label. Fixed-width and
   * weight-independent, so it does not affect the bold-ghost width reservation.
   * Used to differentiate tabs at a glance (e.g. per-platform icons).
   */
  icon?: React.ReactNode
  /**
   * Optional progress for the active tab's underline:
   * - a 0..1 number renders a determinate fill bar (progress toward a target);
   * - 'indeterminate' renders the open-ended indicator: segment accumulation
   *   when `count` is set, else a dotted line;
   * - omitted keeps the plain solid underline (no progress concept).
   */
  progress?: number | 'indeterminate'
  /**
   * The tally behind an 'indeterminate' underline (streak days, check-ins).
   * Renders segment accumulation: solid dots on a faint dotted track, every 10
   * collapsing into a pill (see ProgressBar's `count`). Ignored otherwise.
   */
  count?: number
  /**
   * Optional decorative style for the active tab's underline. Purely visual (no
   * functional meaning) and takes precedence over `progress`:
   * - 'wave' renders a wavy accent line;
   * - 'shimmer' renders a dimmed accent line with a slow full-accent sweep (for
   *   occasional "special" tabs; requires the `.wj-tab-shimmer` utility class,
   *   and falls back to a plain line under reduced motion).
   */
  underline?: 'wave' | 'shimmer'
}

export interface TabBarProps {
  items: TabBarItem[]
  activeId: string | null
  onSelect: (id: string) => void
  className?: string
  /** Inline styles for the root element. */
  style?: React.CSSProperties
}

/**
 * The "wave" decorative underline: a tiled wavy accent line, purely visual.
 * Taller than the solid / progress underlines, so it sits at the bottom and
 * extends upward. The pattern id is per-instance (useId) to avoid collisions.
 * Themeable via the path's CSS stroke. Drifts gently sideways (one wavelength,
 * looping seamlessly) via SMIL, gated by prefers-reduced-motion.
 */
function WaveUnderline() {
  const patternId = React.useId()
  const reduced = useReducedMotion()
  return (
    <svg
      aria-hidden
      className="pointer-events-none absolute inset-x-0 bottom-0 h-2 w-full overflow-visible"
    >
      <defs>
        <pattern id={patternId} width="16" height="8" patternUnits="userSpaceOnUse">
          <path
            d="M0,4 Q4,0 8,4 T16,4"
            fill="none"
            strokeWidth="2"
            strokeLinecap="round"
            style={{ stroke: 'var(--color-accent-500)' }}
          />
          {/* Drift one full wavelength (16px) and loop = seamless, since the
              pattern is periodic. Skipped entirely under reduced motion. */}
          {!reduced && (
            <animateTransform
              attributeName="patternTransform"
              type="translate"
              from="0 0"
              to="16 0"
              dur="1.5s"
              repeatCount="indefinite"
            />
          )}
        </pattern>
      </defs>
      <rect width="100%" height="8" fill={`url(#${patternId})`} />
    </svg>
  )
}

/**
 * Sticky frosted tab bar for switching between primary entities.
 *
 * Combines the sticky outer wrapper (backdrop-blur, --header-bg, border-b) and
 * the inner horizontally-scrolling strip. Integrates useTabBarFade internally
 * for the dynamic edge-fade mask. Auto-scrolls the active tab into view on
 * `activeId` change, and re-centers it when the item set changes around it
 * (e.g. a search filter clearing re-adds tabs and shifts every position).
 *
 * The outer wrapper uses `sticky top-0 z-30 -mx-4 -mt-3` so callers should
 * place it as a direct child of the page's full-height scroll container (not
 * wrapped in a sized div) and apply `px-4 pt-3` to the page container.
 *
 * The tab bar fade CSS classes (`tab-bar-fade-left`, `tab-bar-fade-right`,
 * `tab-bar-fade-both`) and the `scrollbar-hide` class must be available in the
 * app's own CSS. Import `@whiskeyjack/design-system/css/utilities` to get them.
 */
export const TabBar = React.forwardRef<HTMLDivElement, TabBarProps>(function TabBar({ items, activeId, onSelect, className, style }, ref) {
  const tabBarRef = React.useRef<HTMLDivElement>(null)
  const fadeClass = useTabBarFade(tabBarRef, items.length)
  const reduced = useReducedMotion()

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (!items.length) return
      const currentIndex = activeId ? items.findIndex((t) => t.id === activeId) : -1

      let nextIndex: number | null = null
      if (e.key === 'ArrowRight') {
        nextIndex = currentIndex < items.length - 1 ? currentIndex + 1 : 0
      } else if (e.key === 'ArrowLeft') {
        nextIndex = currentIndex > 0 ? currentIndex - 1 : items.length - 1
      } else if (e.key === 'Home') {
        nextIndex = 0
      } else if (e.key === 'End') {
        nextIndex = items.length - 1
      }

      if (nextIndex !== null) {
        e.preventDefault()
        const next = items[nextIndex]
        onSelect(next.id)
        // Move DOM focus to the newly selected tab
        const btn = tabBarRef.current?.querySelector<HTMLElement>(
          `[data-tab-id="${next.id}"]`
        )
        btn?.focus()
      }
    },
    [activeId, items, onSelect]
  )

  const scrollTabIntoView = React.useCallback(
    (center = false) => {
      if (!tabBarRef.current || !activeId) return
      const activeBtn = tabBarRef.current.querySelector(
        `[data-tab-id="${activeId}"]`
      ) as HTMLElement | null
      if (!activeBtn) return
      const container = tabBarRef.current

      // Center the active tab in the strip (scrollTo clamps at the edges).
      // offsetLeft is physical, giving the LTR scrollLeft target; in modern-RTL
      // the scroll range is [-(scrollWidth-clientWidth), 0], so shift into it.
      if (center) {
        const ltrLeft = activeBtn.offsetLeft - (container.clientWidth - activeBtn.offsetWidth) / 2
        const left = isRTL(container)
          ? ltrLeft - (container.scrollWidth - container.clientWidth)
          : ltrLeft
        container.scrollTo({ left, behavior: reduced ? 'auto' : 'smooth' })
        return
      }

      const containerRect = container.getBoundingClientRect()
      const btnRect = activeBtn.getBoundingClientRect()
      const pad = 16

      if (btnRect.left < containerRect.left + pad) {
        container.scrollTo({
          left: container.scrollLeft + btnRect.left - containerRect.left - pad,
          behavior: reduced ? 'auto' : 'smooth',
        })
      } else if (btnRect.right > containerRect.right - pad) {
        container.scrollTo({
          left: container.scrollLeft + btnRect.right - containerRect.right + pad,
          behavior: reduced ? 'auto' : 'smooth',
        })
      }
    },
    [activeId, reduced]
  )

  // Selecting a neighbouring tab nudges it into view (minimal scroll). When the
  // ITEM SET changes around a still-selected tab -- e.g. a search filter
  // clearing re-adds the hidden tabs and shifts every position -- the old
  // scroll offset is meaningless, so center the active tab instead.
  const itemsKey = items.map((i) => i.id).join('\n')
  const prevItemsKeyRef = React.useRef(itemsKey)
  React.useEffect(() => {
    const itemsChanged = prevItemsKeyRef.current !== itemsKey
    prevItemsKeyRef.current = itemsKey
    scrollTabIntoView(itemsChanged)
  }, [itemsKey, scrollTabIntoView])

  // Sliding underline: the shared measurement, so the bar, the segmented
  // control and the sidebar cannot drift into travelling differently.
  const indicator = useSlidingIndicator(tabBarRef, activeId, { changeKey: items.length })

  // The active tab's underline appearance: a decorative `underline` style wins,
  // else `progress` (a fill bar or dotted line), else the plain solid bar.
  const activeItem = activeId ? items.find((i) => i.id === activeId) : undefined
  const activeProgress = activeItem?.progress
  const activeUnderline = activeItem?.underline

  return (
    <div
      ref={ref}
      className={cn(
        'sticky top-0 z-30 -mx-4 -mt-3 wj-frost-blur',
        // Cover the top safe-area inset so the frosted bar reaches the top edge
        // with the tab labels below the status bar / notch. The strip's own py-5
        // would stack on top of the full inset, leaving too big a gap below the
        // island, so trim the inset slightly here (clamps to 0 when env()≈0, so
        // web/Android keep their padding). env() only reports real insets in the
        // Tauri iOS webview once the auto content-inset is off (see lib.rs).
        'pt-[calc(env(safe-area-inset-top)_-_0.25rem)]',
        'border-b border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
        className
      )}
      style={{ background: 'var(--header-bg)', ...style }}
    >
      <div
        ref={tabBarRef}
        role="tablist"
        data-tab-bar
        onWheel={(e) => {
          if (tabBarRef.current && e.deltaY !== 0) {
            tabBarRef.current.scrollLeft += e.deltaY
            e.preventDefault()
          }
        }}
        onKeyDown={handleKeyDown}
        className={cn('relative flex gap-4 overflow-x-auto px-4 py-5 scrollbar-hide', fadeClass)}
      >
        {items.map((item) => {
          const isActive = item.id === activeId
          return (
            <button
              key={item.id}
              role="tab"
              aria-selected={isActive}
              tabIndex={isActive ? 0 : -1}
              data-tab-id={item.id}
              data-label={item.label}
              onClick={() => onSelect(item.id)}
              className={cn(
                // Metro-style pivot: no button chrome. Same size for all tabs;
                // the active title carries the heavier weight at full strength,
                // the rest lighter and dimmed. inline-flex lays out an optional
                // leading icon beside the label.
                'wj-focus-ring inline-flex items-center justify-center gap-1.5 px-1 text-sm whitespace-nowrap flex-shrink-0 transition-all',
                'text-[var(--color-text-primary-light)] dark:text-[var(--color-text-primary-dark)]',
                isActive ? 'font-semibold opacity-100' : 'font-normal opacity-40'
              )}
            >
              {item.icon && (
                <span aria-hidden className="flex shrink-0 items-center">
                  {item.icon}
                </span>
              )}
              {/* Reserve each tab's BOLD width via a hidden bold ghost (the label
                  duplicated through ::after) so toggling the active weight never
                  reflows the strip. The visible label centers within it; the icon
                  (fixed width) sits outside so it doesn't affect the reservation. */}
              <span
                data-label={item.label}
                className="text-center after:block after:h-0 after:overflow-hidden after:invisible after:font-semibold after:content-[attr(data-label)]"
              >
                {item.label}
              </span>
            </button>
          )
        })}
        {indicator && (
          <div
            aria-hidden
            className={cn(
              'pointer-events-none absolute bottom-0 h-[3px]',
              reduced ? '' : 'transition-all duration-300 ease-out'
            )}
            style={{ left: indicator.offset, width: indicator.size }}
          >
            {activeUnderline === 'shimmer' ? (
              // Occasional "special" tab (e.g. an aggregate / About tab): a dimmed
              // accent line with a slow full-accent sweep. Reduced motion keeps
              // the plain full-strength line.
              reduced ? (
                <div className="h-full rounded-full bg-[var(--color-accent-500)]" />
              ) : (
                <>
                  <div className="h-full rounded-full bg-[var(--color-accent-500)] opacity-50" />
                  <span aria-hidden className="wj-tab-shimmer absolute inset-0 rounded-full" />
                </>
              )
            ) : activeUnderline === 'wave' ? (
              <WaveUnderline />
            ) : activeProgress === 'indeterminate' ? (
              // Free / count streaks (no target): segment accumulation when the
              // item carries its tally, else the plain dotted line.
              <ProgressBar
                indeterminate
                count={activeItem?.count}
                size="xs"
                decorative
                className="h-full"
              />
            ) : activeProgress == null ? (
              <div className="h-full rounded-full bg-[var(--color-accent-500)]" />
            ) : (
              // End goal / completion: the determinate progress bar (track color
              // from --wj-progress-track, full-accent fill).
              <ProgressBar value={activeProgress} decorative className="h-full" />
            )}
          </div>
        )}
      </div>
    </div>
  )
})

TabBar.displayName = 'TabBar'
